insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'TR', '{"original":"Türkiye Scholarships","en":"Türkiye Scholarships","ru":"Стипендия «Türkiye Burslari»"}'::jsonb, 'full', '{"en":"Government of Türkiye","ru":"Правительство Турции"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; usually covers tuition, accommodation and a monthly allowance. Check the official page for the countries, levels and the application window.","ru":"Для иностранных студентов; обычно покрывает обучение, проживание и ежемесячную стипендию. Страны, уровни и сроки подачи — на официальной странице."}'::jsonb, 'https://turkiyeburslari.gov.tr/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'HU', '{"original":"Stipendium Hungaricum","en":"Stipendium Hungaricum","ru":"Stipendium Hungaricum"}'::jsonb, 'full', '{"en":"Government of Hungary","ru":"Правительство Венгрии"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For students from partner countries; usually covers tuition and a monthly stipend, with accommodation support. Applications go through the national agency of your country.","ru":"Для студентов из стран-партнёров; обычно покрывает обучение и ежемесячную стипендию, помогает с жильём. Заявки подаются через ведомство вашей страны."}'::jsonb, 'https://stipendiumhungaricum.hu/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'DE', '{"original":"DAAD scholarships","en":"DAAD scholarships","ru":"Стипендии DAAD"}'::jsonb, 'partial', '{"en":"German Academic Exchange Service (DAAD)","ru":"Германская служба академических обменов (DAAD)"}'::jsonb, array['master', 'phd']::text[], '{"en":"Many programmes for different countries and levels; the DAAD scholarship database shows the ones open to you.","ru":"Много программ для разных стран и уровней; база стипендий DAAD показывает те, что доступны вам."}'::jsonb, 'https://www.daad.de/en/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'PL', '{"original":"NAWA scholarships","en":"NAWA scholarships","ru":"Стипендии NAWA"}'::jsonb, 'partial', '{"en":"Polish National Agency for Academic Exchange (NAWA)","ru":"Национальное агентство академических обменов Польши (NAWA)"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Several programmes for foreign students and researchers; the conditions differ by programme.","ru":"Несколько программ для иностранных студентов и исследователей; условия зависят от программы."}'::jsonb, 'https://nawa.gov.pl/en', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'CN', '{"original":"Chinese Government Scholarship (CSC)","en":"Chinese Government Scholarship (CSC)","ru":"Правительственная стипендия Китая (CSC)"}'::jsonb, 'full', '{"en":"China Scholarship Council","ru":"Китайский стипендиальный совет"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; the types differ in what they cover. Applications and deadlines are on the official portal.","ru":"Для иностранных студентов; разные типы покрывают разные расходы. Заявки и сроки — на официальном портале."}'::jsonb, 'https://www.campuschina.org/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'KR', '{"original":"Global Korea Scholarship (GKS)","en":"Global Korea Scholarship (GKS)","ru":"Global Korea Scholarship (GKS)"}'::jsonb, 'full', '{"en":"Government of the Republic of Korea","ru":"Правительство Республики Корея"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; covers tuition and a living allowance. Applications through the Korean embassy or a chosen university.","ru":"Для иностранных студентов; покрывает обучение и проживание. Заявки — через посольство Кореи или выбранный университет."}'::jsonb, 'https://www.studyinkorea.go.kr/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'JP', '{"original":"MEXT scholarship","en":"MEXT scholarship","ru":"Стипендия MEXT"}'::jsonb, 'full', '{"en":"Ministry of Education (MEXT), Japan","ru":"Министерство образования Японии (MEXT)"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Japanese Government scholarship for international students; the application route is through the Japanese embassy or a university.","ru":"Стипендия правительства Японии для иностранцев; заявки — через посольство Японии или университет."}'::jsonb, 'https://www.studyinjapan.go.jp/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'FR', '{"original":"Eiffel Excellence Scholarship","en":"Eiffel Excellence Scholarship","ru":"Стипендия Эйфеля (Eiffel Excellence)"}'::jsonb, 'living', '{"en":"French Ministry for Europe and Foreign Affairs","ru":"Министерство Европы и иностранных дел Франции"}'::jsonb, array['master', 'phd']::text[], '{"en":"For master''s and PhD students; the application is made by the French institution, not by the student.","ru":"Для магистров и докторантов; заявку подаёт французское учебное заведение, а не студент."}'::jsonb, 'https://www.campusfrance.org/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'RU', '{"original":"Russian Government Scholarship (quota)","en":"Russian Government Scholarship (quota)","ru":"Квота правительства России на бесплатное обучение"}'::jsonb, 'full', '{"en":"Government of the Russian Federation","ru":"Правительство Российской Федерации"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Free places in Russian universities for foreign citizens; the application is made on the official portal.","ru":"Бесплатные места в российских вузах для иностранных граждан; заявка подаётся на официальном портале."}'::jsonb, 'https://education-in-russia.com/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'GB', '{"original":"Chevening Scholarships","en":"Chevening Scholarships","ru":"Стипендии Chevening"}'::jsonb, 'full', '{"en":"UK Government (FCDO)","ru":"Правительство Великобритании (FCDO)"}'::jsonb, array['master']::text[], '{"en":"One-year master''s in the UK for future leaders from eligible countries; work experience is required.","ru":"Годичная магистратура в Великобритании для будущих лидеров из подходящих стран; нужен опыт работы."}'::jsonb, 'https://www.chevening.org/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'US', '{"original":"Fulbright Foreign Student Program","en":"Fulbright Foreign Student Program","ru":"Программа Фулбрайта для иностранных студентов"}'::jsonb, 'full', '{"en":"US Department of State","ru":"Госдепартамент США"}'::jsonb, array['master', 'phd']::text[], '{"en":"Graduate study in the USA; applications go through the Fulbright commission or the US embassy of your country.","ru":"Обучение в магистратуре и аспирантуре США; заявки — через комиссию Фулбрайта или посольство США в вашей стране."}'::jsonb, 'https://foreign.fulbrightonline.org/', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', 'AU', '{"original":"Australia Awards","en":"Australia Awards","ru":"Australia Awards"}'::jsonb, 'full', '{"en":"Australian Government","ru":"Правительство Австралии"}'::jsonb, array['master', 'phd']::text[], '{"en":"Postgraduate scholarships for people from eligible countries; check the official page for your country.","ru":"Стипендии для магистратуры и аспирантуры для жителей подходящих стран; свою страну проверьте на официальной странице."}'::jsonb, 'https://www.dfat.gov.au/people-to-people/australia-awards', 'published', now(), '2026-10-07');
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at) values ('country', null, '{"original":"Erasmus Mundus Joint Masters","en":"Erasmus Mundus Joint Masters","ru":"Erasmus Mundus (совместные магистерские программы)"}'::jsonb, 'full', '{"en":"European Union","ru":"Европейский союз"}'::jsonb, array['master']::text[], '{"en":"Joint master''s programmes in several European countries; scholarships are given by the programme itself, apply on the programme''s website.","ru":"Совместные магистерские программы в нескольких странах Европы; стипендии выдаёт сама программа, заявка — на её сайте."}'::jsonb, 'https://erasmus-plus.ec.europa.eu/', 'published', now(), '2026-10-07');
